"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["50596"],{41623(e){e.exports=JSON.parse('{"id":"F474","slug":"stablecoin-reserve-income","name":"Stablecoin Reserve Backing and Issuer Income","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Stablecoins","level":"Intermediate","aliases":["stablecoins","reserve ratio","collateralization","T-bill income","de-peg buffer"],"formula":{"latex":"CR=\\\\frac{R}{L},\\\\quad \\\\text{Buffer}=R-L,\\\\quad \\\\text{Income}=R_{tb}\\\\times y","also":[],"text":"Backing ratio = reserve assets / coins in circulation; Buffer = reserves - coins in circulation; Issuer income per year = government bills held x yield (holders usually receive none); Run loss = coins redeemed in a run that cannot be paid from cash = max(0, redemptions - cash)"},"symbols":[{"symbol":"R","meaning":"Reserve assets (cash and short government bills)","unit":"money"},{"symbol":"L","meaning":"Coins in circulation, each redeemable for 1","unit":"money"},{"symbol":"y","meaning":"Yield on the bills","unit":"per year"}],"when_to_use":"Use it to judge how safe a fiat-backed stablecoin is and how the issuer makes money. Full backing in cash and short bills should let every holder redeem at par, but a run on redemptions can exceed the cash on hand. The issuer earns interest on reserves, which is why the business is profitable when rates are high.","worked_example":{"problem":"An issuer has 30bn in cash and 70bn in Treasury bills against 98bn of coins. Bills yield 4.3%. In a run, holders try to redeem 20% of coins at once.","inputs":{"c":30000000000,"t":70000000000,"l":98000000000,"y":4.3,"run":20},"steps":[{"label":"Backing ratio","working":"(30,000,000,000+70,000,000,000) / 98,000,000,000","value":"102.04%"},{"label":"Buffer above coins issued","working":"30,000,000,000+70,000,000,000-98,000,000,000","value":"2,000,000,000.00"},{"label":"Income from bills per year","working":"70,000,000,000 x 0.043","value":"3,010,000,000.00"},{"label":"Redemptions in the run","working":"0.2 x 98,000,000,000","value":"19,600,000,000.00"},{"label":"Cash enough for the run? (1 = yes)","working":"1 if 30,000,000,000>=19,600,000,000 else 0","value":"1"},{"label":"Share of the run covered by cash","working":"min(30,000,000,000 / 19,600,000,000, 1)","value":"100.0%"}],"answer":"The backing ratio is 102.04% and the buffer is 2,000,000,000.00. Annual income from bills is 3,010,000,000.00. A run of 20% means 19,600,000,000.00 to be paid out, which is 1 by cash on hand (1 = cash is enough, 0 = bills would have to be sold quickly). Cash covers 100.0% of that run."},"calculator":{"available":true,"inputs":[{"id":"c","label":"Cash reserves","unit":"money","type":"number","default":30000000000,"hint":""},{"id":"t","label":"Treasury bills held","unit":"money","type":"number","default":70000000000,"hint":""},{"id":"l","label":"Coins in circulation","unit":"money","type":"number","default":98000000000,"hint":""},{"id":"y","label":"Yield on bills","unit":"%","type":"number","default":4.3,"hint":""},{"id":"run","label":"Redemption run size","unit":"%","type":"number","default":20,"hint":""}],"checks":[{"expr":"l>0","message":"Coins in circulation must be above zero."}],"steps":[{"id":"cr","label":"Backing ratio","expr":"(c+t)/l","format":"pct2"},{"id":"buf","label":"Buffer above coins issued","expr":"c+t-l","format":"money"},{"id":"inc","label":"Income from bills per year","expr":"t*y","format":"money"},{"id":"red","label":"Redemptions in the run","expr":"run*l","format":"money"},{"id":"cov_","label":"Cash enough for the run? (1 = yes)","expr":"1 if c>=red else 0","format":"num0"},{"id":"cashcov","label":"Share of the run covered by cash","expr":"min(c/red, 1)","format":"pct1"}],"results":["cr","buf","inc","cashcov"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"cr":1.0204081632653061,"buf":2000000000,"inc":3009999999.9999995,"red":19600000000,"cov_":1,"cashcov":1}},"finder":{"finds":"A stablecoin\'s backing, income and run risk","needs":"Cash, bills, coins in circulation, yield, run size"},"related":[{"slug":"bank-run-liquidity-shortfall","name":"Bank Run: Liquidity Shortfall and Fire-Sale Loss"},{"slug":"mmf-nav-break-the-buck","name":"Money Market Fund NAV and Breaking the Buck"},{"slug":"lcr-nsfr","name":"Basel Liquidity Ratios: LCR and NSFR"}],"related_ids":["F356","F362","F387"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>C</mi><mi>R</mi><mo>=</mo><mfrac><mi>R</mi><mi>L</mi></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Buffer</mtext><mo>=</mo><mi>R</mi><mo>\u2212</mo><mi>L</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Income</mtext><mo>=</mo><msub><mi>R</mi><mrow><mi>t</mi><mi>b</mi></mrow></msub><mo>\xd7</mo><mi>y</mi></mrow><annotation encoding=\\"application/x-tex\\">CR=\\\\frac{R}{L},\\\\quad \\\\text{Buffer}=R-L,\\\\quad \\\\text{Income}=R_{tb}\\\\times y</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>C</mi><mi>R</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle CR</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mfrac><mi>R</mi><mi>L</mi></mfrac></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\frac{R}{L}</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mtext>Buffer</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\text{Buffer}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>R</mi><mo>\u2212</mo><mi>L</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =R-L</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mtext>Income</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\text{Income}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><msub><mi>R</mi><mrow><mi>t</mi><mi>b</mi></mrow></msub><mo>\xd7</mo><mi>y</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =R_{tb}\\\\times y</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"srisk","name":"SRISK (Systemic Risk Contribution)"},"next":{"slug":"stock-split","name":"Stock Split"},"lesson":null,"total":522}')}}]);